#include <vector>
using namespace std;

int r, c;
bool state[10][10000];
bool linemap[10][10000];
int mapcount;

int getnum(bool status[10][10000]) {
    int num = 0;
    for (int i = 0; i < r; i++) {
        for (int j = 0; j < c; j++) {
            num += status[i][j];
        }
    }
    return num;
}

void adjust() {
    for (int j = 0; j < c; j++) {
        int num0 = 0, num1 = 0;
        for (int k = 0; k < r; k++) {
            if (linemap[k][j]) num1++;
            else num0++;
        }
        if (num0 > num1) {
            for (int k = 0; k < r; k++) {
                // Only toggle if num0 is greater than num1
                linemap[k][j] = !linemap[k][j];
            }
        }
    }
}

int creatlinemap() {
    int max = 0;
    for (int i = 0; i < mapcount; i++) {
        for (int j = 0; j < r; j++) {
            for (int k = 0; k < c; k++) {
                linemap[j][k] = (i & (1 << j)) ? state[j][k] : !state[j][k];
            }
        }
        adjust();
        max = std::max(max, getnum(linemap));
    }
    return max;
}

int main() {
    while (scanf("%d %d", &r, &c) == 2) {
        if (r * c == 0) return 0;
        mapcount = 1 << r; // Use bit shift for better performance
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                scanf("%d", &state[i][j]);
            }
        }
        printf("%d\n", creatlinemap());
    }
}

